# Generated by multigit's release workflow (packaging/render-channels.sh), which
# fills in the version and the sha256 of the release tarball and pushes the result
# to paxel/homebrew-tap as Formula/multigit.rb. Do not edit it there by hand.
class Multigit < Formula
  desc "Desktop dashboard for many git repositories"
  homepage "https://github.com/paxel/multigit"
  url "https://github.com/paxel/multigit/releases/download/v0.4.0/multigit-0.4.0-x86_64-linux.tar.gz"
  version "0.4.0"
  sha256 "10f58101b41399b6d276942a8abd484fbd05fd20a7512b33ba5badde77f6e0ab"
  license "MIT"

  # macOS gets the app through the cask of the same name.
  depends_on arch: :x86_64
  depends_on :linux

  def install
    libexec.install Dir["*"]
    # A symlink, not a wrapper script: the app finds this stable path back from
    # its Cellar binary and writes it into its own menu entry.
    bin.install_symlink libexec/"multigit"

    # An absolute Exec: a desktop session does not read Homebrew's shell
    # environment, so its bin directory is not on the session's PATH. The icon
    # stays a theme name: the step below puts the PNG into ~/.local/share/icons.
    inreplace libexec/"io.github.paxel.multigit.desktop" do |entry|
      entry.gsub! "Exec=multigit", "Exec=#{opt_bin}/multigit"
    end

    # The helper and everything it copies live together, so it finds the icon
    # next to itself. A wrapper rather than a symlink, for the same reason.
    (libexec/"install-icon.sh").chmod 0755
    (bin/"multigit-install-icon").write <<~SH
      #!/bin/sh
      exec "#{opt_libexec}/install-icon.sh" "$@"
    SH
    (bin/"multigit-install-icon").chmod 0755

    # Also in Homebrew's own share, for the sessions that do read it.
    (share/"applications").mkpath
    cp libexec/"io.github.paxel.multigit.desktop", share/"applications/io.github.paxel.multigit.desktop"
    (share/"icons/hicolor/256x256/apps").mkpath
    cp libexec/"icon_256.png", share/"icons/hicolor/256x256/apps/multigit.png"
  end

  # Homebrew's share directory is not on a desktop session's XDG_DATA_DIRS, so
  # the entry above alone stays invisible to menus. This puts the menu entry and
  # the icon into ~/.local/share, which every session reads. A home that cannot
  # be written must not fail the install: the app writes the same entry itself
  # on every start.
  post_install_steps do
    run "install-icon.sh", base: :libexec, must_succeed: false
  end

  def caveats
    <<~EOS
      multigit runs your system's git; install it from your distribution if
      it is missing.

      The install puts multigit into your application menu under
      ~/.local/share. If it is missing there, for another user on this
      machine, or with a custom XDG_DATA_HOME, run:

        multigit-install-icon

      Before brew uninstall, to take the menu entry out again:

        multigit-install-icon --uninstall
    EOS
  end

  test do
    assert_predicate libexec/"multigit", :exist?
  end
end
